// The bundled programming manual: lookups, link resolution, search and routes.
// Content is generated by scripts/sync-manual.mjs (src/docs/content) — see that script.

import type { ImageSourcePropType } from "react-native";

import { CHAPTER_MARKDOWN } from "./content/chapters";
import { MANUAL_FIGURES } from "./content/figures";
import { MANUAL_MANIFEST } from "./content/manifest";
import { REFERENCE, REFERENCE_CATEGORIES } from "./content/reference";
import { MANUAL_SCREENS } from "./content/screens";
import { generatedMarkdown } from "./generatedChapters";
import { Block, inlineText, parseMarkdown } from "./markdown";
import type { ManualChapterMeta, ManualFigure, ManualPart, RefEntry } from "./types";

export const manual = MANUAL_MANIFEST;
export const chapters: ManualChapterMeta[] = MANUAL_MANIFEST.chapters;
export const reference: RefEntry[] = REFERENCE;

const lc = (s: string) => s.toLowerCase();

// ── Chapters ─────────────────────────────────────────────────────────────────

const parsed = new Map<string, Block[]>();

/** A chapter by manifest id, file stem ("06-motion") or stem without its number ("motion"). */
export function chapterMeta(key: string): ManualChapterMeta | undefined {
  const k = lc(key);
  return chapters.find(c => lc(c.id) === k)
    ?? chapters.find(c => lc(c.file) === k)
    ?? chapters.find(c => lc(c.file.replace(/^(\d+|[A-Z])-/, "")) === k);
}

/** "Chapter 6" / "Appendix A". */
export function chapterLabel(c: ManualChapterMeta): string {
  return /^\d+$/.test(c.number) ? `Chapter ${c.number}` : `Appendix ${c.number}`;
}

/** Chapters grouped by manifest part (one unnamed group when the manifest has no parts). */
export function chapterGroups(): { part?: ManualPart; chapters: ManualChapterMeta[] }[] {
  if (manual.parts.length === 0) return [{ chapters }];
  const groups = manual.parts
    .map(part => ({ part, chapters: chapters.filter(c => c.part === part.id) }))
    .filter(g => g.chapters.length > 0);
  const loose = chapters.filter(c => !c.part || !manual.parts.some(p => p.id === c.part));
  return loose.length ? [...groups, { chapters: loose }] : groups;
}

/** The chapter parsed into blocks — its Markdown, then any section generated from the reference (cached). */
export function chapterBlocks(id: string): Block[] {
  const meta = chapterMeta(id);
  if (!meta) return [];
  let b = parsed.get(meta.id);
  if (!b) {
    const md = CHAPTER_MARKDOWN[meta.id] ?? "";
    const gen = meta.generated ? generatedMarkdown(meta.generated) : "";
    b = parseMarkdown([md, gen].filter(Boolean).join("\n\n"));
    parsed.set(meta.id, b);
  }
  return b;
}

export type ChapterHeading = { id: string; text: string; level: number };

/** The chapter's ## / ### headings (the in-chapter jump list). */
export function chapterHeadings(id: string): ChapterHeading[] {
  return chapterBlocks(id)
    .filter((b): b is Extract<Block, { t: "heading" }> => b.t === "heading" && b.level >= 2 && b.level <= 3)
    .map(b => ({ id: b.id, text: b.text, level: b.level }));
}

export function adjacentChapters(id: string): { prev?: ManualChapterMeta; next?: ManualChapterMeta } {
  const i = chapters.findIndex(c => c.id === id);
  return { prev: i > 0 ? chapters[i - 1] : undefined, next: i >= 0 ? chapters[i + 1] : undefined };
}

// ── Reference ────────────────────────────────────────────────────────────────

/** A reference entry by step type, keyword, alias or block name (case-insensitive). */
export function findRefEntry(key: string | undefined | null): RefEntry | undefined {
  if (!key) return undefined;
  const k = lc(key);
  return reference.find(e => lc(e.type) === k)
    ?? reference.find(e => lc(e.keyword) === k)
    ?? reference.find(e => e.aliases.some(a => lc(a) === k))
    ?? reference.find(e => lc(e.name) === k);
}

export function categoryLabel(key: string, live?: { key: string; label: string }[]): string {
  return REFERENCE_CATEGORIES.find(c => c.key === key)?.label
    ?? live?.find(c => c.key === key)?.label
    ?? key.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/^./, c => c.toUpperCase());
}

/** Category order: the bundled reference's, then any the live catalog adds. */
export function categoryOrder(live?: { key: string }[]): string[] {
  const out: string[] = [];
  const add = (k: string) => { if (!out.includes(k)) out.push(k); };
  REFERENCE_CATEGORIES.forEach(c => add(c.key));
  live?.forEach(c => add(c.key));
  return out;
}

/** "Wait <ms> | Wait until …" → one line per form (a " | " at bracket depth 0 before a word). */
export function splitSyntax(s: string): string[] {
  const out: string[] = [];
  let depth = 0, from = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if ("[(<{".includes(c)) depth++;
    else if ("])>}".includes(c)) depth = Math.max(0, depth - 1);
    else if (depth === 0 && s.startsWith(" | ", i) && /[A-Za-z@$]/.test(s[i + 3] ?? "")) {
      out.push(s.slice(from, i).trim());
      from = i + 3;
      i += 2;
    }
  }
  out.push(s.slice(from).trim());
  return out.filter(Boolean);
}

// ── Figures and screenshots ──────────────────────────────────────────────────

const base = (src: string) => src.split(/[?#]/)[0].split("/").pop() ?? src;

export function figureFor(src: string): ManualFigure | undefined {
  return MANUAL_FIGURES[base(src)];
}

export function screenFor(src: string): ImageSourcePropType | undefined {
  return MANUAL_SCREENS[base(src)];
}

// ── Links ────────────────────────────────────────────────────────────────────

export type DocTarget =
  | { kind: "contents" }
  | { kind: "chapter"; id: string; anchor?: string }
  | { kind: "step"; key: string }
  | { kind: "external"; url: string };

const stepTarget = (key: string): DocTarget | null => {
  const e = findRefEntry(key);
  return e ? { kind: "step", key: e.type } : null;
};

/**
 * Resolve a Markdown link. Understands chapter files ("06-motion.md#anchor", "../chapters/x.md",
 * an id like "motion"), in-page anchors ("#anchor"), the reference ("ref:MoveL" / "step:MoveL",
 * "reference.md#MoveL", "reference/MoveL", the instructions chapter with a step anchor, a bare
 * keyword) and web links. Null = not a manual link.
 */
export function resolveHref(href: string, fromChapter?: string): DocTarget | null {
  const h = href.trim();
  if (/^(https?:|mailto:)/i.test(h)) return { kind: "external", url: h };
  const scheme = /^(ref|step|srs|keyword):(.+)$/i.exec(h);
  if (scheme) return stepTarget(scheme[2]);

  const hash = h.indexOf("#");
  const rawPath = hash >= 0 ? h.slice(0, hash) : h;
  const anchor = hash >= 0 ? h.slice(hash + 1) : undefined;
  if (!rawPath) {
    if (!anchor) return null;
    // The manual is also built as one document (the PDF), so its links are anchors: "#ref-MoveL"
    // for an instruction, "#errors" (a chapter id) for a chapter.
    const ref = /^ref-(.+)$/i.exec(anchor);
    if (ref && findRefEntry(ref[1])) return stepTarget(ref[1]);
    const ch = chapters.find(c => c.id === anchor);
    if (ch && ch.id !== fromChapter) return { kind: "chapter", id: ch.id };
    if (fromChapter) {
      const ch = chapterMeta(fromChapter);
      if (ch?.generated === "steps" && findRefEntry(anchor)) return stepTarget(anchor);
      return { kind: "chapter", id: fromChapter, anchor };
    }
    return stepTarget(anchor);
  }
  const path = rawPath.replace(/^(\.\.?\/)+/, "").replace(/^(docs\/)?(manual\/)?/, "").replace(/^chapters\//, "");
  const stem = path.replace(/\.(md|json)$/i, "").replace(/\/$/, "");

  if (/^reference$/i.test(stem)) return (anchor && stepTarget(anchor)) || { kind: "contents" };
  const refPath = /^reference\/(.+)$/i.exec(stem);
  if (refPath) return stepTarget(refPath[1]);
  if (/^(index|readme|contents)$/i.test(stem)) return { kind: "contents" };

  const ch = chapterMeta(stem);
  if (ch) {
    if (ch.generated === "steps" && anchor && findRefEntry(anchor)) return stepTarget(anchor);
    return { kind: "chapter", id: ch.id, anchor };
  }
  return stepTarget(stem);
}

/** Expo Router href for a manual page. */
export function manualRoute(t: DocTarget): string | null {
  switch (t.kind) {
    case "contents": return "/(tabs)/program/manual";
    case "chapter": return `/(tabs)/program/manual-chapter?id=${encodeURIComponent(t.id)}${t.anchor ? `&anchor=${encodeURIComponent(t.anchor)}` : ""}`;
    case "step": return `/(tabs)/program/manual-step?key=${encodeURIComponent(t.key)}`;
    default: return null;
  }
}

// ── Search ───────────────────────────────────────────────────────────────────

export type SearchHit =
  | { kind: "chapter"; id: string; title: string; heading?: { id: string; text: string }; snippet: string; score: number }
  | { kind: "step"; key: string; title: string; snippet: string; score: number };

type Section = { chapter: ManualChapterMeta; heading?: { id: string; text: string }; text: string };
let sections: Section[] | null = null;

function blockText(b: Block): string {
  switch (b.t) {
    case "heading": return b.text;
    case "paragraph": return inlineText(b.children);
    case "list": return b.items.map(it => it.children.map(blockText).join(" ")).join(" ");
    case "table": return [...b.head, ...b.rows.flat()].map(inlineText).join(" ");
    case "code": return b.text;
    case "quote": return b.children.map(blockText).join(" ");
    case "figure": return b.alt + " " + (b.title ?? "");
    default: return "";
  }
}

function allSections(): Section[] {
  if (sections) return sections;
  const out: Section[] = [];
  for (const c of chapters) {
    let cur: Section = { chapter: c, text: "" };
    out.push(cur);
    for (const b of chapterBlocks(c.id)) {
      if (b.t === "heading" && b.level >= 2) {
        cur = { chapter: c, heading: { id: b.id, text: b.text }, text: b.text };
        out.push(cur);
      } else cur.text += " " + blockText(b);
    }
  }
  sections = out;
  return out;
}

function snippetAround(text: string, q: string): string {
  const flat = text.replace(/\s+/g, " ").trim();
  const i = lc(flat).indexOf(q);
  if (i < 0) return flat.slice(0, 110);
  const from = Math.max(0, i - 40);
  return (from > 0 ? "…" : "") + flat.slice(from, i + q.length + 70) + (i + q.length + 70 < flat.length ? "…" : "");
}

/** Search the instructions and chapter sections (substring match, ranked by where it matched). */
export function searchManual(query: string, entries: RefEntry[] = reference): SearchHit[] {
  const q = lc(query.trim());
  if (q.length < 2) return [];
  const hits: SearchHit[] = [];
  for (const e of entries) {
    const kw = lc(e.keyword);
    const head = lc(`${e.keyword} ${e.name} ${e.aliases.join(" ")}`);
    const param = e.params.find(p => lc(`${p.key} ${p.label} ${p.inText} ${p.help}`).includes(q));
    const note = param ? undefined : [e.description, ...e.notes].find(n => lc(n).includes(q));
    const score = kw === q ? 100 : kw.startsWith(q) ? 80 : head.includes(q) ? 60 : param || note ? 20 : 0;
    if (score) {
      const snippet = score >= 60 || (!param && !note) ? e.description
        : param ? `${param.label}${param.inText ? ` (${param.inText})` : ""}${param.help ? ` — ${param.help}` : ""}`
        : snippetAround(note!.replace(/`/g, ""), q);
      hits.push({ kind: "step", key: e.type, title: `${e.keyword} — ${e.name}`, snippet, score });
    }
  }
  for (const s of allSections()) {
    // The instruction chapter repeats the step list — the step hits already cover it.
    if (s.chapter.generated === "steps" && s.heading) continue;
    const title = lc(s.heading?.text ?? s.chapter.title);
    const score = title.includes(q) ? (s.heading ? 50 : 55) : lc(s.text).includes(q) ? 10 : 0;
    if (score) hits.push({ kind: "chapter", id: s.chapter.id, title: s.chapter.title, heading: s.heading, snippet: snippetAround(s.text, q), score });
  }
  return hits.sort((a, b) => b.score - a.score).slice(0, 50);
}
